TConstArrayView<FElysiumTaskArmRow> ElysiumTaskArms::All()
{
	return MakeArrayView(GTaskArms);
}

void FElysiumTaskOpTable::Build(const FElysiumIdNamespace& Tasks, FSpaceForClass SpaceForClass)
{
	TSet<int32> ArmedIds;
	for (const FElysiumTaskArmRow& Row : GTaskArms)
	{
		const FElysiumLocalIdSpace* Space = SpaceForClass(Row.RetailClass);
		const int32 Global = Space != nullptr ? Space->LocalToGlobal(Row.LocalTaskId) : INDEX_NONE;
		if (Global != INDEX_NONE)
		{
			ArmedIds.Add(Global);
		}
	}
	BuildFromArmed(Tasks, ArmedIds);
}

void FElysiumTaskOpTable::BuildFromArmed(const FElysiumIdNamespace& Tasks, const TSet<int32>& ArmedGlobalIds)
{
	Reset();
	for (const TPair<FString, int32>& Row : Tasks.Rows())
	{
		Names.Add(Row.Value, Row.Key);
		if (ArmedGlobalIds.Contains(Row.Value))
		{
			Armed.Add(Row.Value);
		}
		else
		{
			// An identity no arm names. (An arm whose id no registered name holds is a switch case
			// retail keeps for a task no text registers; it is not counted as ported.)
			Unported.Add(Row.Key, 0);
			UnportedById.Add(Row.Value, Row.Key);
		}
	}
}

const FString& FElysiumTaskOpTable::NameOf(int32 GlobalTaskId) const
{
	const FString* Found = Names.Find(GlobalTaskId);
	return Found != nullptr ? *Found : GNoName;
}

int32 FElysiumTaskOpTable::Measure(const FElysiumScheduleManager& Manager)
{
	for (TPair<FString, int32>& Row : Unported)
	{
		Row.Value = 0;
	}

	int32 UnportedSteps = 0;
	for (const FElysiumScheduleProgram& Program : Manager.Programs())
	{
		for (const FElysiumScheduleStep& Step : Program.Tasks)
		{
			if (const FString* Key = UnportedById.Find(Step.TaskId))
			{
				++Unported.FindChecked(*Key);
				++UnportedSteps;
			}
		}
	}
	return UnportedSteps;
}

void FElysiumTaskOpTable::Reset()
{
	Armed.Reset();
	Names.Reset();
	Unported.Reset();
	UnportedById.Reset();
}
